<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import PanelLayout from '../../components/panel/PanelLayout.vue'
import AppIcon from '../../components/ui/AppIcon.vue'
import StatusBadge from '../../components/ui/StatusBadge.vue'
import { request } from '../../services/http'
const hoy=new Date().toLocaleDateString('en-CA',{timeZone:'America/Guayaquil'})
const fecha=ref(hoy), frecuencia=ref(''),manifiesto=ref([]),opciones=ref({frecuencias:[],rutas:[],buses:[]}),busqueda=ref(''),filtro=ref('')
const codigo=ref(''),validado=ref(null),mensaje=ref(''),error=ref(''),ocupado=ref(false),cargando=ref(true),video=ref(null),camara=ref(false),entrada=ref(null)
let stream,temporizador,lector,codigoValidado='',desmontado=false,solicitud=0
const filas=computed(()=>manifiesto.value.filter(r=>(!filtro.value||(filtro.value==='abordo'?r.abordado_en:!r.abordado_en))&&[r.reserva_id,r.pasajero,r.asiento,r.origen,r.destino].some(v=>String(v??'').toLowerCase().includes(busqueda.value.toLowerCase()))))
const abordados=computed(()=>manifiesto.value.filter(r=>r.abordado_en).length)
const viajes=computed(()=>opciones.value.frecuencias.map(f=>({...f,nombre:`${opciones.value.rutas.find(r=>r.id===f.ruta_id)?.nombre||'Frecuencia'} · ${f.hora_salida.slice(0,5)} · ${opciones.value.buses.find(b=>b.id===f.bus_id)?.nombre||''}`})))
async function cargar(){const n=++solicitud;cargando.value=true;try{const datos=await request(`/panel/manifiesto?fecha=${fecha.value}${frecuencia.value?`&frecuencia_id=${frecuencia.value}`:''}`);if(n===solicitud)manifiesto.value=datos}catch(e){error.value=e.message}finally{if(n===solicitud)cargando.value=false}}
onMounted(async()=>{document.addEventListener('visibilitychange',visibilidad);try{opciones.value=await request('/panel/opciones')}catch(e){error.value=e.message}await cargar()})
function detener(){clearTimeout(temporizador);stream?.getTracks().forEach(t=>t.stop());if(video.value)video.value.srcObject=null;camara.value=false}
function visibilidad(){if(document.hidden)detener()}
onBeforeUnmount(()=>{desmontado=true;detener();document.removeEventListener('visibilitychange',visibilidad)})
async function validar(valor=codigo.value){if(ocupado.value)return;ocupado.value=true;error.value='';mensaje.value='';validado.value=null
 try{let texto=String(valor).trim();if(texto.startsWith('{')){let datos;try{datos=JSON.parse(texto)}catch{throw new Error('El contenido escaneado no es un QR de boleto válido.')}if(datos.tipo!=='boleto-interprovincial'||typeof datos.codigo!=='string')throw new Error('El QR no corresponde a un boleto del sistema.');texto=datos.codigo}
 if(!/^[\w-]{20,64}$/.test(texto))throw new Error('Introduce el código del boleto o escanea su QR completo.')
 validado.value=await request('/boletos/validar',{method:'POST',body:JSON.stringify({codigo:texto})});codigoValidado=texto;detener()
 }catch(e){error.value=e.message;codigoValidado=''}finally{ocupado.value=false}}
async function registrar(){if(ocupado.value||!validado.value)return;ocupado.value=true;error.value=''
 try{const r=await request('/boletos/abordar',{method:'POST',body:JSON.stringify({codigo:codigoValidado})});mensaje.value=`Acceso registrado. ${r.pasajero||'Pasajero'} · Asiento ${r.asiento} · Reserva #${r.reserva_id}.`;validado.value=null;codigo.value='';codigoValidado='';fecha.value=hoy;await cargar();entrada.value?.focus()}
 catch(e){error.value=e.message;validado.value=null;await cargar()}finally{ocupado.value=false}}
async function iniciar(){error.value='';try{
 if(!('BarcodeDetector' in window))throw new Error('Este navegador no permite lectura QR con cámara. Puedes usar un lector externo o pegar el contenido del QR.')
 if(!navigator.mediaDevices?.getUserMedia)throw new Error('La cámara requiere HTTPS o una conexión local compatible.')
 lector=new window.BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}})
 if(desmontado){detener();return}camara.value=true;video.value.srcObject=stream;await video.value.play()
 async function detectar(){if(!camara.value)return;try{const encontrados=await lector.detect(video.value);if(encontrados.length){codigo.value=encontrados[0].rawValue;detener();await validar(codigo.value);return}temporizador=setTimeout(detectar,350)}catch{error.value='No se pudo leer la cámara. Reintenta o usa un lector externo.';detener()}}
 detectar()
 }catch(e){error.value=e.name==='NotAllowedError'?'No se concedió acceso a la cámara. Puedes utilizar un lector externo.':e.message;detener()}}
</script>
<template><PanelLayout titulo="Un acceso ágil. Un viaje seguro." descripcion="Verifica el boleto, confirma al pasajero y registra su ingreso al bus." etiqueta="Control de abordaje">
<template #acciones><span class="status-badge success"><i></i>Control del día</span></template>
<div v-if="error" class="alert error" role="alert">{{ error }}</div><div v-if="mensaje" class="alert success" role="status">{{ mensaje }}</div>
<div class="section-grid boarding-grid"><section class="card scanner-card"><div class="card-heading"><div><h2>Verificar boleto</h2><p>Lector QR, cámara o código de acceso.</p></div><AppIcon name="scan"/></div><div class="card-body"><div v-if="!validado" class="scanner-placeholder"><AppIcon name="scan" :size="56"/><p>El siguiente pasajero comienza aquí.</p><small>El código se verifica antes de registrar el acceso.</small></div><form @submit.prevent="validar()"><label class="form-field">Código o contenido del QR<input ref="entrada" v-model="codigo" :disabled="ocupado" required maxlength="1000" autocomplete="off" placeholder="Escanea o pega el código del boleto" @input="validado=null"></label><div class="scan-actions"><button class="btn-primary" :disabled="ocupado||!codigo.trim()"><AppIcon name="check" :size="17"/>{{ ocupado?'Verificando…':'Verificar boleto' }}</button><button class="btn-secondary" type="button" :disabled="camara||ocupado" @click="iniciar"><AppIcon name="scan" :size="17"/>Cámara</button></div></form><div v-show="camara" class="camera-preview"><video ref="video" muted playsinline></video><button class="btn-secondary" @click="detener">Detener cámara</button></div>
<div v-if="validado" class="boarding-preview"><span class="status-badge success"><i></i>Boleto válido para hoy</span><h3>{{ validado.pasajero||'Pasajero registrado' }}</h3><dl class="detail-list"><div><dt>Recorrido</dt><dd>{{ validado.origen }} → {{ validado.destino }}</dd></div><div><dt>Bus</dt><dd>{{ validado.bus }}</dd></div><div><dt>Asiento / reserva</dt><dd>{{ validado.asiento }} · #{{ validado.reserva_id }}</dd></div><div><dt>Tarifa</dt><dd>{{ validado.tipo_pasajero.replaceAll('_',' ').toLowerCase() }}</dd></div></dl><p class="small muted" style="margin-top:20px">Verifica la identidad del pasajero y sus documentos antes de permitir el acceso.</p><button class="btn-primary" :disabled="ocupado" @click="registrar"><AppIcon name="check" :size="18"/>{{ ocupado?'Registrando…':'Confirmar abordaje' }}</button></div></div></section>
<div class="stack"><div class="boarding-metrics"><article class="card metric-card"><span class="metric-label">Pasajeros esperados</span><strong class="metric-value">{{ manifiesto.length }}</strong><p class="metric-foot">Boletos confirmados</p></article><article class="card metric-card"><span class="metric-label">A bordo</span><strong class="metric-value">{{ abordados }}</strong><p class="metric-foot">{{ manifiesto.length-abordados }} por abordar</p></article></div><section class="card"><div class="card-heading"><div><h2>Lista de pasajeros</h2><p>Solo viajes de la cooperativa de tu cuenta.</p></div><button class="icon-button" aria-label="Actualizar pasajeros" :disabled="cargando" @click="cargar"><AppIcon name="refresh"/></button></div><div class="card-body manifest-filters"><label class="form-field">Fecha<input v-model="fecha" type="date" @change="fecha&&cargar()"></label><label class="form-field">Salida<select v-model="frecuencia" @change="cargar"><option value="">Todas las salidas</option><option v-for="f in viajes" :key="f.id" :value="f.id">{{ f.nombre }}</option></select></label><div class="search-control full-width"><AppIcon name="search" :size="17"/><input v-model="busqueda" class="control" aria-label="Buscar pasajero o asiento" placeholder="Buscar pasajero o asiento…"></div><label class="form-field full-width"><span class="sr-only">Estado de abordaje</span><select v-model="filtro" aria-label="Estado de abordaje"><option value="">Todos los pasajeros</option><option value="pendientes">Por abordar</option><option value="abordo">A bordo</option></select></label></div>
<div v-if="cargando" class="loading-state" role="status">Consultando pasajeros…</div><div v-else-if="!filas.length" class="empty-state"><AppIcon name="ticket" :size="30"/><h3>No hay pasajeros para este filtro</h3><p>Selecciona otra fecha o salida.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Pasajero</th><th>Asiento</th><th>Estado</th></tr></thead><tbody><tr v-for="r in filas" :key="r.reserva_id"><td><strong>{{ r.pasajero||'Pasajero' }}</strong><small>{{ r.origen }} → {{ r.destino }} · {{ r.hora_salida.slice(0,5) }}</small><small>{{ r.bus }} · Documento termina en {{ r.cedula?.slice(-4)||'—' }}</small></td><td class="numeric">{{ r.asiento }}</td><td><StatusBadge :estado="r.abordado_en?'ABORDADO':'POR_ABORDAR'"/></td></tr></tbody></table></div></section></div></div>
</PanelLayout></template>
<style scoped>.boarding-grid{grid-template-columns:minmax(300px,.9fr) minmax(0,1.3fr)}.scanner-placeholder{padding:16px 10px 30px;text-align:center;color:var(--brand)}.scanner-placeholder p{font-size:13px;margin:18px 0 4px;color:var(--text)}.scanner-placeholder small{color:var(--muted);font-size:11px}.scan-actions{display:flex;gap:10px;margin-top:14px;flex-wrap:wrap}.boarding-preview{border-top:1px solid var(--border);margin-top:25px;padding-top:25px}.boarding-preview h3{font-size:22px;font-weight:550;margin:18px 0 24px;overflow-wrap:anywhere}.boarding-metrics{display:grid;grid-template-columns:1fr 1fr;gap:16px}.manifest-filters{display:grid;grid-template-columns:140px minmax(0,1fr);gap:12px;padding-bottom:20px}.camera-preview{margin:20px 0 0}.camera-preview video{display:block;width:100%;border-radius:7px;margin-bottom:10px}.scanner-card{position:sticky;top:20px}@media(max-width:1200px){.boarding-grid{grid-template-columns:1fr}.scanner-card{position:static}}@media(max-width:620px){.manifest-filters{grid-template-columns:1fr}.boarding-metrics{gap:10px}}</style>
